(1, 'menu_cache_enabled', 'true', 'boolean', 'performance', 'Enable Menu Cache', 'تفعيل التخزين المؤقت للقائمة', 'Cache menu items for better performance', 'تخزين عناصر القائمة مؤقتًا لأداء أفضل', 1, '2026-01-31 11:21:06', '2026-01-31 11:21:06'),
(2, 'menu_cache_duration', '3600', 'integer', 'performance', 'Cache Duration (seconds)', 'مدة التخزين المؤقت (بالثواني)', 'How long to cache menu items', 'مدة تخزين عناصر القائمة مؤقتًا', 1, '2026-01-31 11:21:06', '2026-01-31 11:21:06'),
(3, 'show_icons_in_menu', 'true', 'boolean', 'display', 'Show Icons in Menu', 'عرض الأيقونات في القائمة', 'Display icons next to menu items', 'عرض الأيقونات بجانب عناصر القائمة', 0, '2026-01-31 11:21:06', '2026-01-31 11:21:06'),
